class BaseConfig {
    protected int timeout = 30; // Hidden field
    public int getTimeout() { return timeout; }
}

class CustomConfig extends BaseConfig {
    protected int timeout = 60; // Hides BaseConfig.timeout

    @Override
    public int getTimeout() { return timeout; }

    public void printBothTimeouts() {
        System.out.println("Child timeout:  " + timeout);       // 60
        System.out.println("Parent timeout: " + super.timeout); // 30 (Accessed via super!)
    }
}

public class HiddenFieldAccessDemo {
    public static void main(String[] args) {
        CustomConfig cfg = new CustomConfig();
        cfg.printBothTimeouts();

        BaseConfig baseRef = cfg;
        // Through getters, behavior is always consistent and polymorphic!
        System.out.println("Polymorphic getter: " + baseRef.getTimeout()); // 60
    }
}

