class ServerConfig {
    public int port;
    public ServerConfig(int p) { this.port = p; }
    public int getPort() { return port; }
}

class SecureServerConfig extends ServerConfig {
    // BUG: Accidental field hiding! Shadows ServerConfig.port!
    public int port;
    public SecureServerConfig(int p) {
        super(p);
        // this.port remains 0!
    }
}

public class ConfigBug {
    public static void main(String[] args) {
        ServerConfig cfg = new SecureServerConfig(8443);
        System.out.println("Port: " + cfg.getPort());
    }
}

