class LevelA {
    public String label = "A";
}

class LevelB extends LevelA {
    public String label = "B";
}

class LevelC extends LevelB {
    public String label = "C";
}

public class MultiLevelHidingApp {
    public static void main(String[] args) {
        LevelC c = new LevelC();
        LevelB b = c;
        LevelA a = c;

        System.out.println("From C ref: " + c.label);
        System.out.println("From B ref: " + b.label);
        System.out.println("From A ref: " + a.label);
    }
}
